function applyExperimentMetadata(records){if(!records?.length||!records.some(r=>{const e=ExperimentStore.get().experiments.find(e=>e.id===r.id);return e&&(e.name!==r.name||e.executor!==r.executor)}))return;applyingExperimentMetadata=true;try{for(const r of records){const e=ExperimentStore.get().experiments.find(e=>e.id===r.id);if(e){e.name=r.name;e.executor=r.executor}}ExperimentStore.save()}finally{applyingExperimentMetadata=false}}
