function researchTodoMarkup(t,i){const model={...t,status:t.done?'done':t.status},late=overdue(model);return `<div class="doc-task ${late?'overdue':''} ${t.done?'done':''}" data-research-todo="${i}"><div class="doc-task-top"><button class="task-checkbox" data-research-complete="${i}" aria-label="完成任务 ${safe(t.text)}" aria-pressed="${t.done}">${t.done?icon('check'):''}</button><div class="doc-task-name" contenteditable="plaintext-only" role="textbox" aria-label="编辑待办 ${safe(t.text)}" data-research-name="${i}">${safe(t.text)}</div><button class="task-urgent-flag" data-research-priority="${i}">${t.priority==='high'?'紧急':'···'}</button></div><div class="doc-task-meta"><button class="task-prop status-${model.status}" data-research-status="${i}">${taskStatusName(model)}</button><button class="task-prop owner-prop" data-research-owner="${i}">@${safe(t.owner)}</button><button class="task-prop date-prop ${late?'overdue':''}" data-research-date="${i}">${icon('calendar')}${dueLabel(model)}</button></div><div class="task-node-link">${safe(task)}</div></div>`}
function dockView(){const count=todos.filter(researchUrgent).length;return `<div class="research-dock-wrap">${dock?`<section class="research-dock copilot-dock open"><div class="dock-heading"><div><h3>${dock==='assets'?'项目资产':'任务待办'}</h3><span>${safe(task)} / ${dock==='assets'?'拖入对话框以引用':'文档式编辑 · 示例待办'}</span></div><button id="research-dock-close" class="icon-btn" aria-label="收起面板">${icon('chevron')}</button></div><div class="dock-body ${dock==='assets'?'asset-mode':''}">${dock==='assets'?`<div class="asset-search-toolbar"><label class="asset-search">${icon('folder')}<input id="research-asset-search" placeholder="搜索项目或任务文件" aria-label="搜索项目资产" value="${safe(researchQuery)}"></label><button type="button" class="asset-toolbar-btn" id="research-search-assets" aria-label="搜索任务资产文件" title="搜索文件">${icon('asset-search-icon')}</button><button type="button" class="asset-toolbar-btn asset-upload-btn" id="research-upload-assets" aria-label="上传任务资产文件" title="上传文件">${icon('asset-upload-icon')}</button></div><div id="research-asset-rows"></div><div class="asset-dock-footer"><small id="research-selection-hint">拖动文件到下方输入框</small><button class="btn primary" id="research-quote-selected" ${chosen.size?'':'disabled'}>引用选中</button></div>`:`${UnifiedTasks.render(unifiedRows(),{},true,isLocked())}`}</div></section>`:''}<div class="copilot-tools"><button class="copilot-tool" data-dock="assets" aria-expanded="${dock==='assets'}">${icon('folder')}项目资产 <small>${researchCatalog().length}</small><svg class="tool-chevron"><use href="#chevron"/></svg></button><button class="copilot-tool" data-dock="todos" aria-expanded="${dock==='todos'}">${icon('icon-todo-list')}待办 <small class="urgent-count ${count?'':'quiet'}">${count?count+' 紧急':'无紧急'}</small><svg class="tool-chevron"><use href="#chevron"/></svg></button></div></div>`}
