function assetRows(){const root=q('#research-asset-rows');if(!root)return;root.innerHTML='<div class="dock-asset-section">任务共享</div>'+researchCatalog().filter(n=>documentLabel(n).toLowerCase().includes(researchQuery.toLowerCase())).map(n=>`<div class="dock-asset" draggable="true" tabindex="0" aria-label="${safe(documentLabel(n))}，双击或按回车打开" title="双击打开文档" data-research-file="${safe(n)}"><input type="checkbox" aria-label="选择 ${safe(n)}" ${chosen.has(n)?'checked':''}><span class="asset-file">${assetIcon(n)}</span><span class="dock-file-text"><strong>${safe(documentLabel(n))}</strong><small>${Object.hasOwn(docs,n)?'方案文档':baseline.includes(n)?'示例参考资料':'本次会话导入'}</small></span><button class="quote-asset" aria-label="引用 ${safe(n)}">${icon('plus')}</button></div>`).join('');if(!root.querySelector('.dock-asset'))root.innerHTML='<div class="todo-empty">没有匹配的文件</div>';root.querySelectorAll('[data-research-file]').forEach(row=>{const name=row.dataset.researchFile,open=()=>{dock='';openDoc(name)};row.querySelector('input').onchange=e=>{e.target.checked?chosen.add(name):chosen.delete(name);selectionHint()};row.querySelector('button').onclick=()=>referenceFiles([name]);row.ondblclick=e=>{if(!e.target.closest('input,button'))open()};row.onkeydown=e=>{if(e.key==='Enter'&&!e.target.closest('input,button')){e.preventDefault();open()}};row.ondragstart=e=>{e.dataTransfer.setData('application/x-research-assets',JSON.stringify(chosen.has(name)?[...chosen]:[name]));e.dataTransfer.effectAllowed='copy'};});selectionHint()}
