async function importResearchFiles(fileList,attach=false){const selected=[...fileList];if(!selected.length)return;for(const file of selected){const text=/\.(md|txt|csv|json)$/i.test(file.name)?(await file.text()).slice(0,60000):'该格式暂不支持文本预览，请保留本机原件。';files.push({name:file.name,text,file,conversationId});if(attach)references.add(file.name)}save();render();toast('已上传 '+selected.length+' 个文件，仅保留在本次页面会话')}
