 if(q('#research-asset-search')){assetRows();const search=()=>{researchQuery=q('#research-asset-search').value;assetRows()};q('#research-asset-search').oninput=search;q('#research-asset-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();search()}};q('#research-search-assets').onclick=()=>{search();q('#research-asset-search').focus()};q('#research-upload-assets').onclick=()=>q('#research-upload-files').click();q('#research-quote-selected').onclick=()=>referenceFiles([...chosen])}
