 all('[data-research-date]').forEach(b=>b.onclick=()=>{const i=+b.dataset.researchDate,p=popup(b,`<div class="task-popover-title">截止时间 · 北京时间</div><input type="datetime-local" aria-label="任务截止时间" value="${safe(todos[i].due||'')}"><div class="date-actions"><button data-save-due>保存时间</button><button data-clear-due>清除</button></div>`);p.querySelector('[data-save-due]').onclick=()=>{changeTodo(i,{due:p.querySelector('input').value});closeTaskPopup()};p.querySelector('[data-clear-due]').onclick=()=>{changeTodo(i,{due:''});closeTaskPopup()}});
 const add=q('#research-new-task');if(add){let owner='林晓';add.oninput=()=>{const match=add.textContent.match(/@([^\s@]*)$/);if(match)showOwners(add,value=>{owner=value;add.textContent=add.textContent.replace(/@[^\s@]*$/,'').trim();add.focus()},match[1])};add.onkeydown=e=>{if(e.key==='Enter'&&!e.isComposing&&!taskPopup){e.preventDefault();const text=add.textContent.trim();if(!text)return;todos.push({text,done:false,status:'todo',owner,due:'',priority:'normal'});save();render();q('#research-new-task').focus()}}}
 const form=q('.research-composer');form.ondragover=e=>{e.preventDefault();form.classList.add('chat-drop-active')};form.ondragleave=()=>form.classList.remove('chat-drop-active');form.ondrop=async e=>{e.preventDefault();form.classList.remove('chat-drop-active');const raw=e.dataTransfer.getData('application/x-research-assets');if(raw){try{referenceFiles(JSON.parse(raw).filter(n=>researchCatalog().includes(n)))}catch{}}else if(e.dataTransfer.files.length){for(const f of e.dataTransfer.files){files.push({name:f.name,text:/\.(md|txt|csv|json)$/i.test(f.name)?(await f.text()).slice(0,60000):'该格式暂不支持文本预览',conversationId});references.add(f.name)}render()}};
 const panel=q('.research-dock');if(panel){const available=q('.research-dock-wrap').getBoundingClientRect().top-q('.research-panel-head').getBoundingClientRect().bottom-7;panel.style.setProperty('--dock-room',Math.max(110,available)+'px')}
