function parallelWorkItems(){return flowWorkspace?.node?.workItemsMode==='parallel'}
function activeSequenceItem(){const sequence=guidedSequence(),selected=sequence.find(item=>item.id===conversationId);return selected&&!selected.done?selected:sequence.find(item=>!item.done&&item.status==='doing')||sequence.find(item=>!item.done)}
function taskOperation(){const status=taskState(phase,task),schemaBlocked=guidedProject&&task==='需求确认'&&schemaInputActive(),sequence=guidedSequence(),current=activeSequenceItem(),remaining=current?sequence.filter(item=>!item.done&&item!==current):[],next=!parallelWorkItems()&&current?sequence[sequence.indexOf(current)+1]:null,lastStep=task==='SOP审批'?' · 完成后生成研发阶段 1 并进入首个任务':' · 完成后进入下一工作包',sequenceCopy=current?parallelWorkItems()?`当前 TODO：${safe(current.text)}${remaining.length?' · 另有 '+remaining.length+' 项并行进行中':' · 完成后进入下一工作包'}`:`当前 TODO：${safe(current.text)}${next?' · 完成后进入“'+safe(next.text)+'”':lastStep}`:'全部内部任务已完成',action=current&&status==='进行中'?'<button class="btn primary" id="complete-sequence-item">完成任务</button>':!schemaBlocked&&flowWorkspace&&flowWorkspace.phase===phase&&flowWorkspace.sub===sub&&flowWorkspace.node.name===task&&status==='进行中'&&!sequence.length?'<button class="btn primary" id="complete-flow-node-task">完成阶段任务</button>':phase==='项目立项'&&task==='技术调研'&&status==='进行中'?'<button class="btn primary" id="complete-stage-task">完成阶段任务</button>':'';return `<div class="stage-task-operation ${sequence.length?'is-sequential':''}"><div><span class="task-state-badge" data-progress="${status}">${stateIcon(status)}${status}</span><small>${sequence.length?sequenceCopy:schemaBlocked?'请先通过 Agent 对话确认项目 Schema':status==='已完成'?'任务内容已锁定，可继续上传资料和对话':status==='进行中'?'核对待办与交付后，可完成本任务':'等待前序任务完成，可先整理资料'}</small></div>${action}</div>`}
const sequenceDialog=document.createElement('dialog');sequenceDialog.className='completion-dialog sequence-completion-dialog';sequenceDialog.setAttribute('aria-labelledby','sequence-completion-title');document.body.append(sequenceDialog);
function confirmSequenceItem(){const current=activeSequenceItem();if(!current||busy)return;const sequence=guidedSequence(),parallel=parallelWorkItems(),pending=sequence.filter(item=>!item.done&&item!==current),previewNext=pending.find(item=>item.status==='doing')||pending[0],completionCopy=previewNext?(parallel?'完成后将继续处理另一项并行 TODO“':'完成后将自动进入下一任务“')+safe(previewNext.text)+'”。':task==='SOP审批'?'完成后将生成研发阶段 1，并自动进入首个研发工作包的第一项任务。':'这是当前工作包的最后一项 TODO，完成后将自动进入下一工作包。';sequenceDialog.innerHTML=`<h2 id="sequence-completion-title">确认完成“${safe(current.text)}”？</h2><p>${completionCopy}</p><p class="research-muted">此操作只记录当前 TODO 的本地演示进度，不代表真实审批或授权签核。</p><div class="completion-actions"><button class="btn" data-cancel-sequence>继续检查</button><button class="btn primary" data-confirm-sequence>确认完成任务</button></div>`;sequenceDialog.querySelector('[data-cancel-sequence]').onclick=()=>sequenceDialog.close();sequenceDialog.querySelector('[data-confirm-sequence]').onclick=()=>{current.done=true;current.status='done';current.agentWorking=false;syncTaskExecutionState();const next=sequence.find(item=>!item.done&&item.status==='doing')||sequence.find(item=>!item.done);save();sequenceDialog.close();if(next){switchTodoConversation(next.id);return}document.dispatchEvent(new CustomEvent('synmat:request-flow-complete',{detail:{...flowWorkspace,autoContinue:true}}))};sequenceDialog.showModal()}
const completionDialog=document.createElement('dialog');completionDialog.className='completion-dialog';completionDialog.setAttribute('aria-labelledby','completion-title');completionDialog.innerHTML='<h2 id="completion-title">完成技术调研任务？</h2><p id="completion-description"></p><p class="research-muted">确认后任务状态变为已完成，待办、材料编辑及 Copilot 操作将锁定。立项评审进入进行中。</p><div class="completion-actions"><button class="btn" data-cancel-completion>继续检查</button><button class="btn primary" data-confirm-completion>确认完成</button></div>';document.body.append(completionDialog);
completionDialog.querySelector('[data-cancel-completion]').onclick=()=>completionDialog.close();
completionDialog.querySelector('[data-confirm-completion]').onclick=()=>{if(phase!=='项目立项'||task!=='技术调研'||busy)return;technicalComplete=true;save();completionDialog.close();editing=false;closeTaskPopup();render()};
function confirmCompletion(automatic){if(isLocked()||busy)return;const pending=todos.filter(t=>!t.done).length;q('#completion-description').textContent=automatic?'所有待办已完成。是否确认完成项目立项阶段的技术调研任务？':pending?'仍有 '+pending+' 项待办未完成，请完成待办后再提交。':'请确认 SOP 文档与调研材料已核实、准备就绪。';completionDialog.querySelector('[data-confirm-completion]').disabled=pending>0;completionDialog.showModal()}
function checkCompletion(){if(guidedProject&&task==='客户准入'){const confirmed=todos.find(todo=>/阶段任务确认/.test(todo.text))?.done;const hasFeedback=/## 本轮反馈/.test(docs['用户反馈记录.md']||'');if(confirmed&&hasFeedback&&!feedbackDispatched){feedbackDispatched=true;save();document.dispatchEvent(new CustomEvent('synmat:round-feedback-confirmed',{detail:{round:flowWorkspace?.node?.round||1,feedback:docs['用户反馈记录.md']}}))}return}if(guidedProject&&flowWorkspace&&phase==='项目立项'&&task==='技术调研')return;if(phase!=='项目立项'||task!=='技术调研'||technicalComplete)return;const ready=todos.length>0&&todos.every(t=>t.done);if(!ready){completionPrompted=false;return}if(!completionPrompted){completionPrompted=true;confirmCompletion(true)}}
function lockCompleted(){if(!isLocked())return;desk.querySelectorAll('[data-done],[data-todo],[data-delete],#research-add,#research-edit,[data-research-complete],[data-research-status],[data-research-owner],[data-research-priority],[data-research-date]').forEach(el=>el.disabled=true);desk.querySelectorAll('[contenteditable]').forEach(el=>el.contentEditable='false');q('.research-composer').inert=false;q('.research-composer').title='任务已完成，可继续对话与上传资料';}

// Add SOP evidence to the existing simulation workspace without replacing its model assets.
const simulationExample=developmentTaskExamples['路线筛选'][0];
for(const [i,text] of simulationExample.todos.entries()){const id='sop-simulation-'+i;if(!ensureDocumentTasks().some(t=>t.id===id))ensureDocumentTasks().push({id,name:text,status:'todo',owner:'林晓',due:'',priority:'normal',nodeId:'macro1'})}
for(const [name,text] of Object.entries(simulationExample.assets)){if(!assets.some(a=>a.name===name))assets.push({name,text,type:'SOP示例资料'})}
try{localStorage.setItem('synmat-thermal-v3',JSON.stringify(state))}catch{}
renderTodos();renderAssets();

desk.addEventListener('click',event=>{if(!event.target.closest('[data-close]'))return;queueMicrotask(()=>{if(opened.length&&active==='overview'){active=opened.at(-1);render()}applyWorkspaceEmphasis()})});
document.addEventListener('click',event=>{if(dock!=='assets'||desk.classList.contains('hidden')||event.target.closest('.research-dock,[data-dock]'))return;dock='';render()});
document.addEventListener('synmat:flow-progress',e=>{flowSummary=e.detail;if(flowWorkspace){const record=flowSummary.tasks?.[flowWorkspace.phase+'/'+flowWorkspace.node.id];if(record)flowWorkspace.status=record.status;}updateProgress()});
function dismissWorkPackageMenu(){const menu=q('#task-menu');if(menu&&!menu.classList.contains('hidden')){menu.classList.add('hidden');q('#task-switch').setAttribute('aria-expanded','false')}}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#task-menu,#task-switch'))dismissWorkPackageMenu()},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape')dismissWorkPackageMenu()},true);
 document.addEventListener('synmat:open-flow-task',e=>{document.body.classList.remove('projects-active','overview-active','research-flow-active','flow-canvas-active','flow-v3-active');document.body.classList.add('task-workspace-active');window.ProjectWorkspace?.activate('task');all('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav==='任务'));flowWorkspace=e.detail;navigate(flowWorkspace.phase);if(flowWorkspace.sub)selectSubstage(flowWorkspace.sub);selectTask(flowWorkspace.node.name);q('#task-menu').classList.add('hidden');q('#task-switch').setAttribute('aria-expanded','false');const node=flowWorkspace.internalNode,special=flowWorkspace.previewType||(node&&WorkspaceNodeOpening.kind(node)==='experiment'?'experiment':simulationNode(node)?'simulation':'');if(special==='experiment')openElnPreview(node,true);else if(special==='simulation')openSimulationPreview(true);else if(!computationWorkspace()){workspaceView='list';save();render();if(flowWorkspace.openAction==='conversation-assets')openConversationAssets(node?.id);else{if(flowWorkspace.autoFocusFirstTask){const first=firstActiveDialogue();if(first&&first.id!==conversationId)switchTodoConversation(first.id)}if(node){const action=WorkspaceNodeOpening.kind(node);if(action==='file')openDoc(node.name);else if(action==='chat'||action==='document')openConversationAssets(node.id)}}if(flowWorkspace.node.workItems?.length&&todos.length&&todos.every(todo=>todo.done)&&flowWorkspace.status!=='已完成')requestAnimationFrame(()=>document.dispatchEvent(new CustomEvent('synmat:request-flow-complete',{detail:{...flowWorkspace,autoContinue:true}})))}requestAnimationFrame(fitDesk)});
document.addEventListener('synmat:open-flow-task',e=>{if(e.detail?.openAction!=='scope-conversation')return;requestAnimationFrame(()=>{const id=e.detail.collaborationScope?.id;if(id)switchTodoConversation(id)})});
// The same entry serves simulation, default workspaces and flow-created tasks.
q('.task-menu-title').addEventListener('click',e=>{const trigger=e.target.closest('[data-view-stage-workflow]');if(!trigger)return;e.preventDefault();e.stopPropagation();q('#task-menu').classList.add('hidden');q('#task-switch').setAttribute('aria-expanded','false');const current=flowWorkspace&&flowWorkspace.phase===phase&&flowWorkspace.sub===sub&&flowWorkspace.node.name===task?flowWorkspace.node.id:null;document.dispatchEvent(new CustomEvent('synmat:request-stage-workflow',{detail:{phase,sub,task,taskId:current}}));});
document.addEventListener('synmat:task-workspace-visible',()=>{document.body.classList.remove('projects-active','overview-active','research-flow-active');document.body.classList.add('task-workspace-active');window.ProjectWorkspace?.activate('task');all('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav==='任务'));ProjectWorkspaceController.setBreadcrumb([phase,...(sub?[sub]:[]),task].join(' / '));updateProgress();if(!computationWorkspace()){workspaceView='list';applyWorkspaceEmphasis();save();workspaceNeedsRefresh=false;render()}else if(workspaceNeedsRefresh&&desk.getBoundingClientRect().height>0){workspaceNeedsRefresh=false;render()}requestAnimationFrame(fitDesk)});
document.addEventListener('synmat:experiments-updated',()=>{if(applyingExperimentMetadata)return;if(desk.getBoundingClientRect().height>0)render();else workspaceNeedsRefresh=true});
document.addEventListener('synmat:simulation-complete',()=>{showTaskMenu();updateProgress()});
document.addEventListener('synmat:edit-task-node',event=>{if(desk.classList.contains('hidden'))return;const index=todos.findIndex(todo=>todo.id===event.detail?.id);if(index<0||todos[index].done)return;TaskTodoEditor.open(taskCanvasContext(),index)});
function reconcileActiveWorkspaceTasks(){
 if(!flowWorkspace||!workspaceKey)return;
 const changed=syncTaskExecutionState();
 const first=flowWorkspace.autoFocusFirstTask?firstActiveDialogue():null;
 if(first&&first.id!==conversationId){switchTodoConversation(first.id);return}
 if(changed){save();render()}
}
document.addEventListener('synmat:open-flow-task',()=>queueMicrotask(reconcileActiveWorkspaceTasks));
document.addEventListener('synmat:task-workspace-visible',()=>queueMicrotask(reconcileActiveWorkspaceTasks));
updateProgress();
SynmatPhaseNavigation.mount(q('.project-context'),{
 selector:'[data-phase]',
 getState(p){const names=p==='研发'?Object.keys(developmentTaskExamples):p==='量产'?['小试','中试','量产']:[];return {phase,selected:sub,items:names.map((name,i)=>({id:name,name,count:p==='研发'?developmentTaskExamples[name].length:3,status:flowSummary?.substageStatuses?.[p+'/'+(p==='研发'?'S':'L')+(i+1)]||(p==='研发'&&i===0?'已完成':p==='研发'&&i===1?'进行中':'待开始')}))}},
 onSubstage(p,id){if(phase!==p)navigate(p);selectSubstage(id);q('#task-menu').classList.add('hidden');q('#task-switch').setAttribute('aria-expanded','false');q('#task-switch').focus({preventScroll:true});window.dispatchEvent(new Event('resize'))}
});
